/** A symbol's bars as the PricePoint series the snapshot carries. */
export function daily(symbol: string): PricePoint[] {
  const b = BARS[symbol];
  if (!b) throw new Error(`no fixture for ${symbol}`);
  return SESSIONS.map((at, i) => ({
    at,
    price: b.c[i],
    open: null,
    high: b.h[i],
    low: b.l[i],
    volume: b.v[i],
  }));
}
